import { AI_SUMMARY_CLIENT_TIMEOUT_MS } from './aiSummaryApi';
import type { AiSummaryFailure } from './aiSummaryApi';

/** Shown under the section heading (`UI_WORKFLOW.md` §8.1). */
export const AI_SUMMARY_NOTICE =
  'Generated by an AI model from the calculated results above. It may be incomplete or wrong; the calculated values are authoritative.';

/**
 * Fixed text written by EVA (not generated) shown under every AI summary: the assumptions and
 * limits of the AI reading itself. The calculation assumptions are in the report's
 * "Assumptions and limitations" section.
 */
export const AI_SUMMARY_READING_NOTES: readonly string[] = [
  'The AI only sees the currency, the four confirmed values at one reporting date, and the results EVA calculated from them. It does not know the project’s scope, tasks, causes, or plans, so it cannot say why performance changed.',
  'Recommendations are starting points for the project manager to investigate, not decisions.',
  'Forecasts in the text assume the current cost efficiency continues, as described in “Assumptions and limitations” below.',
  'Every value shown in this section comes from EVA’s calculation, not from the AI. If the wording and the calculated results disagree, the calculated results are correct.',
];

interface FailureMessage {
  text: string;
  retry: boolean;
}

/** Short, fixed messages by category. Nothing from the response body is ever shown. */
export function describeFailure(failure: AiSummaryFailure): FailureMessage {
  const complete = 'The report above is complete without it.';
  switch (failure.kind) {
    case 'timeout':
      return {
        text: `The AI summary took too long (${AI_SUMMARY_CLIENT_TIMEOUT_MS / 1000} seconds). ${complete}`,
        retry: true,
      };
    case 'unreachable':
      return { text: 'The AI service is not running. Start it and try again.', retry: true };
    case 'invalidResponse':
      return {
        text: 'The AI response could not be used for this analysis, so it is not shown. Try again.',
        retry: true,
      };
    case 'server':
      break;
  }

  const { code, retryable, retryAfterSeconds } = failure;
  switch (code) {
    case 'rate_limited':
      return {
        text:
          retryAfterSeconds === undefined
            ? 'Too many requests. Try again later.'
            : `Too many requests. Try again in ${retryAfterSeconds} ${retryAfterSeconds === 1 ? 'second' : 'seconds'}.`,
        retry: true,
      };
    case 'ai_unavailable':
      return { text: 'The AI service is unavailable. Try again later.', retry: retryable };
    case 'ai_timeout':
      return { text: `The AI service did not respond in time. ${complete}`, retry: retryable };
    case 'invalid_ai_response':
      return {
        text: 'The AI summary did not pass validation, so it is not shown. Try again.',
        retry: retryable,
      };
    case 'ai_not_configured':
      return {
        text: `AI summaries are not available: the local backend has no AI model configured. ${complete}`,
        retry: false,
      };
    case 'ai_provider_error':
    case 'internal_error':
      return { text: 'The AI service returned an error. Try again.', retry: retryable };
    default:
      return {
        text: `The local AI service did not accept the request. ${complete}`,
        retry: retryable,
      };
  }
}
